# -*- coding: utf-8 -*-
"""docs/5.1-测试计划.docx —— 按 game-docs-and-sheets-inventory.md 5.1【S 精简版】写。

清单要求：测什么/不测什么、设备与浏览器矩阵（iOS Safari、Android Chrome、桌面 Chrome、320px 与主流宽度）、
谁测/什么时候测/通过标准。
"""
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
sys.path.insert(0, ROOT)

import docx_kit as k

OUT = os.path.join(ROOT, "docs", "5.1-测试计划.docx")


def main():
    doc = k.new_doc("5.1 测试计划 · v0.1 · 2026-11-04")
    k.title(
        doc,
        "电竞选手模拟器 · 测试计划",
        "测什么 · 在哪儿测 · 谁测 · 算过 · v0.1 · 2026-11-04",
    )

    k.note(
        doc,
        "**现状先说清**：自动化有 61 个单测 + 一组冒烟（本机 Edge，390×844）+ 1000 局批量模拟；"
        "**真机测试：0 次**。所以这份计划的重点不是「怎么测」，是「还差哪几次测」。",
    )

    # ---------------- 一 ----------------
    k.h1(doc, "一", "测什么 / 不测什么")
    k.table(
        doc,
        ["测", "方式", "现在有吗"],
        [
            ["规则核心（成本、胜率、签约、存档、跨年）", "Vitest 单测 61 条", "✅"],
            ["主流程能走通（开局→三格→事件→比赛→结周）", "冒烟：本机 Edge 无头 390×844", "✅"],
            ["数值分布（签约率、达标年份）", "`npm run batch` 1000 局", "✅"],
            ["手机真机兼容（iOS Safari / 低端安卓）", "人工，W5.1 的 10 项", "❌ 0 次"],
            ["320px 窄屏与安全区", "人工 + DevTools 设备模拟", "❌ 只模拟过，没真机"],
            ["脏操作（连点/刷新/断网/返回）", "人工", "❌"],
            ["陌生人可玩性", "**跳过**（用户决定）", "—"],
        ],
        [9.0, 8.6, 4.4],
        size=9,
    )
    k.para(
        doc,
        "**不测**：比赛画面（没有）、音频（没有）、多语言（不做）、联机（不做）、性能压力（单机无并发）。",
    )

    # ---------------- 二 ----------------
    k.h1(doc, "二", "设备与浏览器矩阵")
    k.table(
        doc,
        ["#", "环境", "宽度", "为什么测它", "优先级"],
        [
            ["1", "Android Chrome（中低端，2–4GB 内存）", "360 / 390", "目标平台用户主力；性能与 dvh 最可能出事", "**P0**"],
            ["2", "iOS Safari（iPhone SE / 13 起）", "375 / 390", "安全区、`100dvh`、localStorage 配额差异", "**P0**"],
            ["3", "桌面 Chrome（1280+）", "1280", "投稿审核与截图用", "P1"],
            ["4", "320px 极窄（模拟，非真机）", "320", "最小屏不溢出", "P1"],
            ["5", "微信内置 webview", "—", "平台分享后的实际打开环境", "P2"],
        ],
        [1.0, 7.0, 2.4, 8.4, 2.2],
        size=8,
        caption="表 2-1　P0 两项不跑完，不许投稿",
    )

    # ---------------- 三 ----------------
    k.h1(doc, "三", "谁测 · 什么时候测")
    k.table(
        doc,
        ["测什么", "谁", "何时", "工时"],
        [
            ["单测 + 冒烟 + batch", "AI（跑命令）", "每次改完代码", "0"],
            ["真机 10 项", "你（借一台中低端安卓）", "W5.1，投稿前", "1.5h"],
            ["iOS 一台", "你（自己的手机）", "同上", "含在内"],
            ["320px / 桌面", "AI 用无头 Edge 模拟", "每次构建后", "0"],
            ["陌生人盲测", "**不做**", "—", "0"],
        ],
        [7.0, 8.0, 5.0, 2.0],
        size=9,
    )

    # ---------------- 四 ----------------
    k.h1(doc, "四", "通过标准（三条，全满足才算过）")
    k.table(
        doc,
        ["维度", "标准", "不达标的处理"],
        [
            ["功能", "8 年能打到结局；三格不能空着结周；刷新不丢档；商店买完立即生效", "阻断级，必须修"],
            ["兼容", "P0 两台设备都能开局→打到第 2 周→刷新继续", "阻断级；修不了就把布局降级到 `vh`"],
            ["体验", "点击响应感觉跟手（<100ms）；无横滚；底部按钮不被安全区吃掉", "一般级，可首发后修"],
        ],
        [2.6, 11.0, 6.4],
        size=9,
    )

    # ---------------- 五 ----------------
    k.h1(doc, "五", "脏场景清单（必测，最容易崩）")
    k.table(
        doc,
        ["#", "场景", "预期", "现在的真实情况"],
        [
            ["1", "连点「结束本周」", "只结一次周", "`pendingEvent` 会阻塞，但连点期间未验证"],
            ["2", "事件浮层出现时点页签", "不能跳走或跳走不丢状态", "代码里被阻塞，未在真机验"],
            ["3", "刷新中途（事件未选）", "回到本周，事件重抽或保留", "未验证"],
            ["4", "断网", "无影响（本来零请求）", "理论无影响，未验证"],
            ["5", "返回键（安卓）", "不退出到空白页", "未验证"],
            ["6", "localStorage 被禁", "应提示并降级为不存档", "**没有处理，会静默丢档**"],
            ["7", "存档版本不匹配", "回开局屏，不崩", "已实现（丢弃旧档）"],
            ["8", "空事件池（第 3 年后）", "落 filler 或无事发生", "有 F01/F02 兜底，未验长期表现"],
        ],
        [1.0, 6.0, 6.6, 6.4],
        size=8,
        caption="表 5-1　6 号是唯一「已知没做处理」的，其余是「做了但没在真机验」",
    )

    # ---------------- 六 ----------------
    k.h1(doc, "六", "什么时候可以投稿（判定）")
    k.table(
        doc,
        ["条件", "状态"],
        [
            ["单测 61 全过 + 冒烟全过", "✅ 每次都跑"],
            ["P0 两台真机各走一遍，无阻断", "❌ 未做"],
            ["脏场景 1/3/4 至少验一次", "❌ 未做"],
            ["包体 ≤150 KB", "✅ 89.3 KB"],
            ["控制台无报错", "✅ 冒烟已断言"],
        ],
        [13.6, 6.4],
        size=9,
    )
    k.note(doc, "五条里过了三条。剩下两条都卡在「没有真机」这一件事上——所以 W5.1 是投稿的唯一硬门槛。")

    doc.save(OUT)
    print("saved", OUT)


if __name__ == "__main__":
    main()
